from lib import *
S = SS('f152')
steps = [
    step("用 test_request_context 测一个读取 request 的辅助函数:with app.test_request_context('/items/5?q=hello', method='POST', headers={'User-Agent': 'unit-test'}): 里调用函数,读到 POST /items/5 q=hello ua=unit-test。它只构造并推入一个请求上下文,不经过路由匹配也不执行视图,所以适合单元测试直接读 request 的辅助函数与表单验证逻辑。", t=tl(S(1)), done=lidx(S(1), 'POST /items/5'), kv=KV([['test_request_context', '只推入请求上下文,不走路由与视图']], ['test_request_context'])),
    step("钩子不会自动执行:进入 with 之后事件列表是空的([]),g.pre 也没有值;退出 with 时才执行 teardown_request 与 teardown_appcontext。before_request 的钩子要自己手动调用 app.preprocess_request() 才会执行(之后事件是 before_request、g.pre 被设置,返回值为 None 表示没有短路)。", t=tl(S(2)), done=lidx(S(2), 'with 里面', '退出 with', 'preprocess_request'), kv=KV([['进入 with', '不执行任何钩子'], ['退出 with', '执行 teardown'], ['before_request', '要手动 preprocess_request()']], ['进入 with'])),
    step("full_dispatch_request():在上下文里手动走一遍路由与视图,得到 Response——/items/7 返回 200 与 {i: 7};它执行了 before_request 与 after_request(退出前事件是 ['before_request', 'after_request']),teardown 要等退出 with 之后才补上(['before_request', 'after_request', 'teardown_request', 'teardown_appcontext'])。需要「走完整个钩子链但不想用客户端」时用它。", t=tl(S(3)), done=lidx(S(3), '响应', '退出之后'), kv=KV([['full_dispatch_request()', 'before + 视图 + after'], ['teardown', '退出上下文时']], ['full_dispatch_request()'])),
    step("url_for 的上下文要求:没有任何上下文时抛 RuntimeError「Working outside of application context.」;在 test_request_context 里 url_for('item', i=3) 是 /items/3,_external=True 是 http://localhost/items/3;给 base_url='https://shop.example.test:8443' 则变成 https://shop.example.test:8443/items/3;只有 app_context、没配 SERVER_NAME 时,_external=True 抛「Unable to build URLs outside an active request without 'SERVER_NAME' configured」;配了 SERVER_NAME 之后 app_context 里就能生成 http://shop.example.test/items/3。", t=tl(S(4)), mark=lidx(S(4), '没有任何上下文', '只有 app_context'), done=lidx(S(4), 'test_request_context 里', 'base_url', '配了 SERVER_NAME'), kv=KV([['请求上下文里', 'url_for 取请求的主机'], ['只有 app_context', '需要 SERVER_NAME']], ['只有 app_context'])),
    step("app_context 与 test_request_context 的区别:app_context 里 has_app_context 为 True、has_request_context 为 False(没有 request);test_request_context 里两者都是 True(请求上下文推入时会连带推入应用上下文)。", t=tl(S(5)), done=lidx(S(5), 'app_context:', 'test_request_context:'), kv=KV([['app_context', '只有 current_app 与 g'], ['test_request_context', '再加上 request 与 session']], ['app_context'])),
    step("session 与 json:test_request_context('/', method='POST', json={'k': 'v'}) 里 request.get_json() 读到 {k: v};同一个上下文里 session['x'] = 1 可以直接读写(需要配置 SECRET_KEY)。", t=tl(S(6)), done=lidx(S(6), 'get_json', 'session'), kv=KV([['json=', '请求体的 JSON'], ['session', '可读写,需要 SECRET_KEY']], ['session'])),
]
A = mkartf('f152', 152, 'Flask,测试,test_request_context,上下文,真实验证,动画演示',
    '实测 test_request_context():单独推入请求上下文来测试辅助函数、钩子不会自动执行而 teardown 在退出时执行、preprocess_request 与 full_dispatch_request 手动走钩子、url_for 在不同上下文里的行为与 SERVER_NAME、app_context 与请求上下文的区别。',
    '什么时候该用 test_request_context 而不是 test_client?进入 with 之后哪些钩子执行了?url_for 在测试里为什么有时会报错?这篇逐项验证。',
    [('不执行钩子', '进入 with 之后 before_request 等钩子都没有执行'), ('SERVER_NAME', '只有应用上下文时生成外部 URL 必须配置的项'), ('teardown', '退出 with 时才执行')],
    [('测试读取 request 的函数', '<p>上一篇:<a href="flask-test-client.html">Flask Test Client</a>;下一篇:<a href="flask-test-client-vs-real-http.html">test_client() 与真实 HTTP 请求差异</a>。</p>'), ('钩子与 teardown', None), ('full_dispatch_request', None), ('url_for 与上下文', None), ('两种上下文的区别', None), ('session 与 json', None)],
    steps, [ENV_F, '没有验证:嵌套推入多个请求上下文时 g 与 session 的归属、test_request_context 与 app.test_cli_runner 的配合、before_request 返回响应时 preprocess_request 的短路行为、自定义 session 接口下的行为'], 'test_request_context()')
